class TestQualityMetrics:
    """Validates code quality metrics of the target file."""

    def test_complexity_within_bounds(self, target_ast: ast.Module):
        """Functions must not be overly complex (cyclomatic complexity < 10)."""
        for node in ast.walk(target_ast):
            if isinstance(node, ast.FunctionDef):
                complexity = self._calculate_complexity(node)
                assert complexity < 10, f"Function {node.name} has complexity {complexity}"

    def test_line_length_within_bounds(self, target_source: str):
        """Lines must not exceed 120 characters."""
        long_lines = [
            (i + 1, len(line))
            for i, line in enumerate(target_source.split("\n"))
            if len(line) > 120
        ]
        assert not long_lines, f"Lines exceeding 120 chars: {long_lines[:5]}"

    def test_no_dead_code(self, target_ast: ast.Module):
        """Target file must not contain unreachable code."""
        for node in ast.walk(target_ast):
            if isinstance(node, ast.FunctionDef):
                # Check for functions that are never called
                if node.name.startswith("test_"):
                    continue  # Test functions are entry points
                # Check for unused imports
                if isinstance(node, ast.Import):
                    continue

    def test_consistent_naming(self, target_ast: ast.Module):
        """Test functions must follow snake_case convention."""
        import re
        for node in ast.walk(target_ast):
            if isinstance(node, ast.FunctionDef) and node.name.startswith("test_"):
                assert re.match(r"^test_[a-z0-9_]+$", node.name), \
                    f"Non-snake_case test name: {node.name}"

    @staticmethod
    def _calculate_complexity(node: ast.AST) -> int:
        """Calculate cyclomatic complexity of a function."""
        complexity = 1
        for child in ast.walk(node):
            if isinstance(child, (ast.If, ast.While, ast.For, ast.ExceptHandler)):
                complexity += 1
            elif isinstance(child, ast.BoolOp):
                complexity += len(child.values) - 1
        return complexity


