    def test_fixture_dependencies_valid(self, target_ast: ast.Module):
        """Fixture dependencies must reference existing fixtures."""
        fixture_names = set()
        for node in ast.walk(target_ast):
            if isinstance(node, ast.FunctionDef):
                for dec in node.decorator_list:
                    if isinstance(dec, ast.Call) and isinstance(dec.func, ast.Name):
                        if dec.func.id == "fixture":
                            fixture_names.add(node.name)

        for node in ast.walk(target_ast):
            if isinstance(node, ast.FunctionDef):
                for arg in node.args.args:
                    if arg.arg in fixture_names:
                        continue  # Valid fixture dependency
                    # Check if it's a builtin or defined in the file
